users = {
    'admin': User('admin', 'admin', ['administrator']),
    'teacher': User('teacher', 'teacher', ['teacher']),
    'office': User('office', 'office', ['office', 'billing'])
}
families, children, enrollments, invoices = {}, {}, {}, {}

