    record.history.append({'at': now(), 'by': user, 'action': action, 'detail': detail})
    record.updated_at = now()
    record.updated_by = user

def current_user():
    return session.get('user')

def roles():
    u = users.get(current_user())
    return u.roles if u else []

def require_login(f):
    @wraps(f)
    def wrapper(*a, **k):
        if not current_user():
            return redirect(url_for('login'))
        return f(*a, **k)
    return wrapper

def require_role(*allowed):
    def deco(f):
        @wraps(f)
        def wrapper(*a, **k):
            if not any(r in roles() for r in allowed):
                return jsonify({'error': 'forbidden'}), 403
            return f(*a, **k)
        return wrapper
    return deco

@app.route('/')
