def logout():
    session.clear(); return redirect(url_for('index'))

@app.route('/families', methods=['POST', 'GET'])
@require_login
@require_role('administrator', 'office')
def family_list_create():
    if request.method == 'POST':
        fid = next_id(); f = Family(id=fid, created_at=now(), updated_at=now(), created_by=current_user(), updated_by=current_user(), name=request.json.get('name',''), contact=request.json.get('contact',''))
        families[fid] = f; log(f, current_user(), 'create')
        return jsonify(asdict(f)), 201
    return jsonify([asdict(v) for v in families.values()])

@app.route('/children', methods=['POST', 'GET'])
@require_login
@require_role('administrator', 'office')
def child_list_create():
    if request.method == 'POST':
        cid = next_id(); c = Child(id=cid, created_at=now(), updated_at=now(), created_by=current_user(), updated_by=current_user(), family_id=request.json.get('family_id',0), name=request.json.get('name',''), allergies=request.json.get('allergies',''), immunizations=request.json.get('immunizations',''), classroom=request.json.get('classroom',''))
        children[cid] = c; log(c, current_user(), 'create'); return jsonify(asdict(c)), 201
