@app.route('/invoices', methods=['POST', 'GET'])
@require_login
@require_role('administrator', 'office', 'billing')
def invoice_list_create():
    if request.method == 'POST':
        iid = next_id(); amount = float(request.json.get('amount',0)); inv = Invoice(id=iid, created_at=now(), updated_at=now(), created_by=current_user(), updated_by=current_user(), family_id=request.json.get('family_id',0), child_id=request.json.get('child_id',0), amount=amount, status='unpaid')
