import app as m

client = m.app.test_client()

def login(username, password):
    return client.post('/login', data={'username': username, 'password': password}, follow_redirects=True)

def test_login_and_roles():
    r = login('admin', 'admin')
    assert r.status_code == 200
    assert b'Nenios' in r.data

def test_create_family_child_invoice_and_pay():
    login('admin', 'admin')
    f = client.post('/families', json={'name': 'Smith', 'contact': '555-1111'})
    assert f.status_code == 201
    fam = f.get_json()
    c = client.post('/children', json={'family_id': fam['id'], 'name': 'Ava', 'allergies': 'nuts', 'immunizations': 'up to date'})
    assert c.status_code == 201
    inv = client.post('/invoices', json={'family_id': fam['id'], 'child_id': c.get_json()['id'], 'amount': 100})
    assert inv.status_code == 201
    paid = client.post(f"/invoices/{inv.get_json()['id']}/pay", json={'amount': 40})
    assert paid.get_json()['status'] == 'partial'
    paid2 = client.post(f"/invoices/{inv.get_json()['id']}/pay", json={'amount': 60})
    assert paid2.get_json()['status'] == 'paid'

def test_search_and_archive():
    login('admin', 'admin')
    f = client.post('/families', json={'name': 'Taylor', 'contact': '555-2222'}).get_json()
    c = client.post('/children', json={'family_id': f['id'], 'name': 'Mia'}).get_json()
    arch = client.post(f"/children/{c['id']}/archive")
    assert arch.get_json()['archived'] is True
    s = client.get('/search?q=taylor').get_json()
    assert len(s['families']) >= 1

